"use client";import {FormEvent,useState} from "react";import {useRouter} from "next/navigation";
export function LoginForm(){const router=useRouter();const [error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setError("");const data=Object.fromEntries(new FormData(e.currentTarget));const response=await fetch("/api/session",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(response.ok){router.push("/dashboard");router.refresh()}else setError("We could not sign you in. Check your details and try again.")}return <form onSubmit={submit} className="loginCard"><div className="loginBrand"><span>AM</span><small>Secure dealer workspace</small></div><div><span className="eyebrow">Private access</span><h1>Welcome<br/><span className="accentWord">back.</span></h1><p>Manage inventory, conversations and your digital showroom.</p></div><div className="loginFields"><label><span>Username</span><input name="username" required autoComplete="username" placeholder="Your username"/></label><label><span>Password</span><input name="password" type="password" required autoComplete="current-password" placeholder="Your password"/></label></div><button className="button dark full">Enter workspace <span>↗</span></button>{error&&<p className="loginError" role="alert">{error}</p>}<small className="loginSecurity">Protected access · Activity is recorded</small></form>}
